/* ✅ LEGAL: Using Composition (The "Hole" pattern) */
// ClientWrapper.tsx
'use client';
export default function ClientWrapper({ children }) {
  const [isOpen, setIsOpen] = useState(false);
  return <div onClick={() => setIsOpen(true)}>{isOpen && children}</div>;
}

// page.tsx (Server Component)
import ClientWrapper from './ClientWrapper';
import ServerChild from './ServerChild'; // Fetches DB data

export default function Page() {
  return (
    // The Server Component orchestrates them together!
    <ClientWrapper>
      <ServerChild /> 
    </ClientWrapper>
  );
}
